                            || super::declared_type::copy_record_collection::admitted(types, &ty)
                    })
            })
        }) {
            return;
        }
    }
    diagnostics.push(error(
        program,
        "SPX-T252",
        crate::loop_calls::match_scrutinee_refusal(&value.ty.to_string()),
        scrutinee.span,
    ));
}

pub(super) fn reject_aggregate_equality(
    program: &dyn ProgramSource,
    types: &TypeTable<'_>,
    expression: &Expr,
    value: &CheckedValue,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if types.payload_free_variant(&value.ty) {
        return;
    }
    if let (Type::Named { name, .. }, Some(cases)) = (&value.ty, types.variant_cases(&value.ty)) {
        let example = cases
            .iter()
            .find(|case| case.fields.is_empty())
            .map(|case| {
                format!(
                    ", e.g. `match value {{ {name}::{} {{}} => true, _ => false, }}`",
                    case.name
                )
            })
            .unwrap_or_default();
        diagnostics.push(
            error(
                program,
                "SPX-T207",
                format!(
                    "equality on variant `{}` requires a non-generic variant whose cases all \
                     carry no payload",
                    value.ty
                ),
                expression.span,
            )
            .with_help(format!("test the case with `match` instead{example}")),
        );
        return;
    }
    if matches!(
        value.ty,
        Type::OnceFunction
            | Type::OnceFunctionI64
            | Type::OnceFunctionI64Pair
            | Type::MutFunctionI64
            | Type::Function { .. }
            | Type::Named { .. }
            | Type::ArrayU8(_)
            | Type::Bytes
    ) {
        diagnostics.push(
            error(
                program,
                "SPX-T207",
                "aggregate equality is outside the executable comparison profile",
                expression.span,
            )
            .with_help("compare the relevant scalar fields or match the aggregate case explicitly"),
        );
    }
}

#[allow(clippy::too_many_arguments)]
pub(super) fn require_bool(
    program: &dyn ProgramSource,
    function: &Function,
    contract: &Expr,
    variables: &HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    diagnostics: &mut Vec<Diagnostic>,
    kind: &str,
) {
    require_bool_with_signature(
        program,
        function,
        contract,
        variables,
        functions,
        types,
        result_type,
        diagnostics,
        kind,
        None,
    );
}

#[allow(clippy::too_many_arguments)]
pub(super) fn require_bool_with_signature<'p>(
    program: &'p dyn ProgramSource,
    function: &'p Function,
    contract: &'p Expr,
    variables: &HashMap<String, Binding>,
    functions: &'p HashMap<&'p str, &'p Function>,
    types: &'p TypeTable<'p>,
    result_type: Option<&'p Type>,
    diagnostics: &mut Vec<Diagnostic>,
    kind: &str,
    signature: Option<super::declaration::SignatureOrigin<'p>>,
) {
    contract.visit_calls(&mut |callee, span| {
        if variables.contains_key(callee) { return; }
        if let Some(target) = functions.get(callee) {
            if !target.effects.is_empty() {
                diagnostics.push(
                    error(
                        program,
                        "SPX-C102",
                        format!(
                            "{kind} on `{}` calls effectful function `{callee}` with effects {{{}}}",
                            function.name,
                            target.effects.join(", ")
                        ),
                        span,
                    )
                    .with_help("contracts must be deterministic and effect-free"),
                );
            }
        }
    });
    let mut contract_variables = variables.clone();
    // No freshness from a body or previous clause enters this contract domain.
    for binding in contract_variables.values_mut() {
        binding.contract_local = false;
    }
    if let Some(ty) = result_type {
        // A provisional owned result is readable only in this postcondition
        // scope. It stays immutable and contract transfers still select O105.
        if ty == &function.return_type
            && (matches!(ty, Type::Bytes | Type::String)
                || matches!(ty, Type::Named { name, arguments }
                if name == "Result" && arguments.as_slice() == [Type::Bytes, Type::Bytes]))
        {
            contract_variables.insert(
                "result".to_owned(),
                Binding {
                    contract_local: false,
                    traversal_row: None,
                    ty: ty.clone(),
                    mode: ParamMode::Own,
                    availability: Availability::Available,
                    moved_places: HashMap::new(),
                    definitely_partial: HashSet::new(),
                    native_unit_discard: false,
                    mutable: false,
                    active_loans: BTreeSet::new(),
                    borrow_origin: None,
                },
            );
        }
    }
    let (contract_value, refusal_view) = match signature {
        Some(signature) => check_expr_with_signature_view(
            program,
            function,
            contract,
            &mut contract_variables,
            functions,
            types,
            result_type,
            false,
            diagnostics,
            None,
            None,
            Some(signature),
        ),
        None => check_expr_with_helpers_view(
            program,
            function,
            contract,
            &mut contract_variables,
            functions,
            types,
            result_type,
            false,
            diagnostics,
            None,
            None,
        ),
    };
    if let Some(value) = contract_value {
        if value.native_unit {
            reject_native_unit_value(program, contract, &value, diagnostics);
        } else if value.ty != Type::Bool
            && !refusal_view.is_some_and(|view| view.declared == &Type::Bool)
        {
            diagnostics.push(error(
                program,
                "SPX-C101",
                format!("{kind} on `{}` must be bool", function.name),
                contract.span,
            ));
        }
    }
}

pub(super) fn error(
    program: &dyn ProgramSource,
    code: &'static str,
    message: impl Into<String>,
    span: Span,
) -> Diagnostic {
    let diagnostic = Diagnostic::error(code, message, span).at_path(program.path());
    super::hints::with_authoring_repair_help(diagnostic)
}

pub(super) fn invalid_stable_id(
    program: &dyn ProgramSource,
    code: &'static str,
    subject: impl Into<String>,
    span: Span,
) -> Diagnostic {
    error(
        program,
        code,
        format!(
            "{} has an invalid stable id; persistent identities forbid NUL",
            subject.into()
        ),
        span,
    )
}

pub(super) fn reject_reserved_host_id(
    program: &dyn ProgramSource,
    stable_id: &str,
    kind: &str,
    span: Span,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if crate::vec_ops::by_id(stable_id).is_some() || stable_id == crate::vec_field::ID {
        diagnostics.push(error(
            program,
            "SPX-S113",
            format!(
                "authored {kind} uses stable ID `{stable_id}`, which is reserved by the compiler-owned vector operations"
            ),
            span,
        ));
    } else if crate::string_ops::by_id(stable_id).is_some() {
        diagnostics.push(error(
            program,
            "SPX-S113",
            format!(
                "authored {kind} uses stable ID `{stable_id}`, which is reserved by the compiler-owned string operations"
            ),
            span,
        ));
    } else if crate::host_io_ops::by_id(stable_id).is_some()
        || crate::command_io_ops::by_id(stable_id).is_some()
    {
        diagnostics.push(error(
            program,
            "SPX-S113",
            format!(
                "authored {kind} uses stable ID `{stable_id}`, which is reserved by the compiler-owned host I/O operations"
            ),
            span,
        ));
    }
}

pub(super) fn source_identifier(value: &str) -> bool {
    let mut chars = value.chars();
    let plain = matches!(chars.next(), Some(first) if first == '_' || first.is_ascii_alphabetic())
        && chars.all(|character| character == '_' || character.is_ascii_alphanumeric());
    plain
        && !matches!(
            value,
            "module"
                | "vec_of"
                | "permit"
                | "resource"
                | "fn"
                | "own"
                | "borrow"
                | "shared"
                | "uses"
                | "requires"
                | "ensures"
                | "let"
                | "if"
                | "else"
                | "true"
                | "false"
                | "result"
        )
}

/// Explicit Mutation v1 admits exactly the checked Copy scalar value types.
pub(crate) fn is_scalar_source_type(ty: &Type) -> bool {
    matches!(
        ty,
        Type::I64
            | Type::I32
            | Type::U8
            | Type::Usize
            | Type::Char
            | Type::F32
            | Type::F64
            | Type::Bool
    )
}

edits.new:
//! Lexical call inventory for Function Value v1. `ExprKind::Call` carries a
//! spelling only, so inventory tracks every lexical binding before admitting a
//! global edge. Known references retain their exact target; an incoming or
//! dynamically selected callback conservatively ranges over its signature.

use super::declared_type::function_value_signature;
use crate::ast::program_source::ProgramSource;
use crate::ast::{
    Expr, ExprKind, Function, MatchPattern, RecordMatchFieldPattern, Statement, Type,
};
use std::collections::{BTreeSet, HashMap};

#[derive(Clone)]
enum Binding {
    Shadow,
    Callable {
        signature: Type,
        targets: Option<BTreeSet<String>>,
    },
}

type Scope<'a> = HashMap<&'a str, Binding>;

pub(in crate::source_verify) fn function_value_targets(
    program: &dyn ProgramSource,
    functions: &crate::source_verify::function_map::FunctionMap<'_>,
) -> BTreeSet<String> {
    let mut targets = BTreeSet::new();
    for function in program.functions() {
        let scope = initial_scope(function.payload());
        for expression in function
            .payload()
            .requires
            .iter()
            .chain(std::iter::once(&function.payload().body))
            .chain(&function.payload().ensures)
        {
            visit(
                expression,
                &mut scope.clone(),
                functions,
                &mut targets,
                None,
            );
        }
    }
    targets
}

pub(in crate::source_verify) fn calls(
    function: &Function,
    functions: &crate::source_verify::function_map::FunctionMap<'_>,
    universe: &BTreeSet<String>,
) -> Vec<String> {
    let scope = initial_scope(function.payload());
    let mut output = BTreeSet::new();
    for expression in function
        .payload()
        .requires
        .iter()
        .chain(std::iter::once(&function.payload().body))
        .chain(&function.payload().ensures)
    {
        visit(
            expression,
            &mut scope.clone(),
            functions,
            &mut output,
            Some(universe),
        );
    }
    output.into_iter().collect()
}

fn initial_scope(function: &Function) -> Scope<'_> {
    function
        .payload()
        .params
        .iter()
        .map(|parameter| {
            (
                parameter.name.as_str(),
                match &parameter.ty {
                    signature @ Type::Function { .. } => Binding::Callable {
                        signature: signature.clone(),
                        targets: None,
                    },
                    _ => Binding::Shadow,
                },
            )
        })
        .collect()
}

fn visit(
    expression: &Expr,
    scope: &mut Scope<'_>,
    functions: &crate::source_verify::function_map::FunctionMap<'_>,
    output: &mut BTreeSet<String>,
    universe: Option<&BTreeSet<String>>,
) {
    match &expression.kind {
        ExprKind::Var(name) => {
            if !scope.contains_key(name.as_str())
                && function_value_signature_for(name, functions).is_some()
            {
                output.insert(name.clone());
            }
        }
        ExprKind::Call { name, args, .. } => {
            match scope.get(name.as_str()) {
                Some(Binding::Callable {
                    signature: _,
                    targets: Some(targets),
                }) => output.extend(targets.iter().cloned()),
                Some(Binding::Callable {
                    signature,
                    targets: None,
                }) => {
                    if let Some(universe) = universe {
                        output.extend(candidates(signature, functions, universe));
                    }
                }
                Some(Binding::Shadow) => {}
                None if universe.is_some() => {
                    output.insert(name.clone());
                }
                None => {}
            }
            for argument in args {
                visit(argument, scope, functions, output, universe);
            }
        }
        ExprKind::Block { statements, tail } => {
            let mut block = scope.clone();
            for statement in statements {
                match statement {
                    Statement::Let {
                        name,
                        declared,
                        value,
                        ..
                    } => {
                        visit(value, &mut block, functions, output, universe);
                        block.insert(
                            name,
                            binding_for_let(declared.as_ref(), value, &block, functions),
                        );
                    }
                    Statement::Assign { name, value, .. } => {
                        visit(value, &mut block, functions, output, universe);
                        block.insert(name, Binding::Shadow);
                    }
                    Statement::Unsafe { body, .. } => {
                        visit(body, &mut block, functions, output, universe)
                    }
                    Statement::While {
                        condition, body, ..
                    } => {
                        visit(condition, &mut block, functions, output, universe);
                        visit(body, &mut block, functions, output, universe);
                    }
                    Statement::For {
                        item, values, body, ..
                    }
                    | Statement::ForBorrow {
                        item, values, body, ..
                    }
                    | Statement::ForOwn {
                        item, values, body, ..
                    } => {
                        visit(values, &mut block, functions, output, universe);
                        let mut loop_scope = block.clone();
                        loop_scope.insert(item, Binding::Shadow);
                        if let Statement::ForBorrow {
                            index: Some(index), ..
                        } = statement
                        {
                            loop_scope.insert(&index.name, Binding::Shadow);
                        }
                        visit(body, &mut loop_scope, functions, output, universe);
                    }
                }
            }
            visit(tail, &mut block, functions, output, universe);
        }
        ExprKind::Match {
            scrutinee, arms, ..
        } => {
            visit(scrutinee, scope, functions, output, universe);
            for arm in arms {
                let mut arm_scope = scope.clone();
                shadow_pattern(&arm.pattern, &mut arm_scope);
                if let Some(guard) = &arm.guard {
                    visit(guard, &mut arm_scope, functions, output, universe);
                }
                visit(&arm.value, &mut arm_scope, functions, output, universe);
            }
        }
        _ => {
            let mut index = 0;
            while let Some(child) = expression.child(index) {
                visit(child, scope, functions, output, universe);
                index += 1;
            }
        }
    }
}

fn binding_for_let(
    declared: Option<&Type>,
    value: &Expr,
    scope: &Scope<'_>,
    functions: &crate::source_verify::function_map::FunctionMap<'_>,
) -> Binding {
    let signature = declared
        .cloned()
        .or_else(|| reference_signature(value, scope, functions));
    let Type::Function { .. } = signature.as_ref().unwrap_or(&Type::I64) else {
        return Binding::Shadow;
    };
    let targets = reference_target(value, scope, functions);
    Binding::Callable {
        signature: signature.expect("function type checked above"),
        targets,
    }
}

fn reference_signature(
    value: &Expr,
    scope: &Scope<'_>,
    functions: &crate::source_verify::function_map::FunctionMap<'_>,
) -> Option<Type> {
    if let ExprKind::Closure {
        params,
        return_type,
        ..
    } = &value.kind
    {
        return Some(Type::Function {
            parameters: params.iter().map(|param| param.ty.clone()).collect(),
            result: Box::new(return_type.clone()),
        });
    }
    let ExprKind::Var(name) = &value.kind else {
        return None;
    };
    match scope.get(name.as_str()) {
        Some(Binding::Callable { signature, .. }) => Some(signature.clone()),
        Some(Binding::Shadow) => None,
        None => function_value_signature_for(name, functions),
    }
}

fn reference_target(
    value: &Expr,
    scope: &Scope<'_>,
    functions: &crate::source_verify::function_map::FunctionMap<'_>,
) -> Option<BTreeSet<String>> {
    let ExprKind::Var(name) = &value.kind else {
        return None;
    };
    match scope.get(name.as_str()) {
        Some(Binding::Callable { targets, .. }) => targets.clone(),
        Some(Binding::Shadow) => Some(BTreeSet::new()),
        None if function_value_signature_for(name, functions).is_some() => {
            Some(BTreeSet::from([name.clone()]))
        }
        None => Some(BTreeSet::new()),
    }
}

fn function_value_signature_for(
    name: &str,
    functions: &crate::source_verify::function_map::FunctionMap<'_>,
) -> Option<Type> {
    functions
        .get(name)
        .and_then(|function| function_value_signature(function.payload()))
}

fn candidates(
    signature: &Type,
    functions: &crate::source_verify::function_map::FunctionMap<'_>,
    universe: &BTreeSet<String>,
) -> BTreeSet<String> {
    functions
        .iter()
        .filter(|(name, function)| {
            universe.contains(**name)
                && function_value_signature(function.payload()).as_ref() == Some(signature)
        })
        .map(|(name, _)| (*name).to_owned())
        .collect()
}

fn shadow_pattern<'a>(pattern: &'a MatchPattern, scope: &mut Scope<'a>) {
    match pattern {
        MatchPattern::Binding { name, .. } => {
            scope.insert(name, Binding::Shadow);
        }
        MatchPattern::Record { fields, .. } => {
            for field in fields {
                shadow_field(&field.pattern, scope);
            }
        }
        MatchPattern::Or { alternatives, .. } => {
            for alternative in alternatives {
                shadow_pattern(alternative, scope);
            }
        }
        MatchPattern::Variant { .. }
        | MatchPattern::Wildcard { .. }
        | MatchPattern::Literal { .. } => {}
    }
}
fn shadow_field<'a>(pattern: &'a RecordMatchFieldPattern, scope: &mut Scope<'a>) {
    match pattern {
        RecordMatchFieldPattern::Binding { name, .. } => {
            scope.insert(name, Binding::Shadow);
        }
        RecordMatchFieldPattern::Record { fields, .. } => {
            for field in fields {
                shadow_field(&field.pattern, scope);
            }
        }
        RecordMatchFieldPattern::Wildcard { .. } => {}
    }
}

