fn evidence(
    program: &dyn ProgramSource,
    current: &Function,
    expression: &Expr,
    bindings: &HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    budget: &mut EvidenceBudget,
    depth: usize,
) -> Option<Type> {
