                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T225",
                                format!("generic function `{name}` expects {} explicit type arguments, received {}", target.payload().type_parameters.len(), type_arguments.len()),
                                expression.span,
                            ).with_help(hints::generic_call_help(name)));
                            return None;
                        }
