                            |(params, return_type)| {
                                VerifierFunctionSignature::SourceSpecialized {
                                    function: target,
                                    params,
                                    return_type,
                                }
                            },
                        )
                    });
                    VerifierCallTarget::Ordinary(specialized)
                };
