        );
    compare_scalar_body(
            "module t; @id(\"t.shape\") variant Shape { @id(\"t.shape.dot\") Dot, @id(\"t.shape.empty\") Empty, @id(\"t.shape.square\") Square { @id(\"t.shape.square.side\") side: i64, }, } fn main(left: Shape, right: Shape) -> bool { left == right }",
        );
