        );
    compare_scalar_body(
            "module t; @id(\"t.status\") variant Status { @id(\"t.status.todo\") Todo, @id(\"t.status.done\") Done, } fn main(left: Status, right: Status) -> bool { left == right && left != Status::Done {} }",
