                        } else {
                            *functions.get(name.as_str()).unwrap_or(&0)
                        },
                        u8::saturating_add,
                    ),
                    ExprKind::Block { statements, .. } => {
                        let mut child = 0;
                        for statement in statements {
                            let count = match statement {
                                Statement::While { .. } => 2,
                                Statement::For { .. }
                                | Statement::ForBorrow { .. }
                                | Statement::ForOwn { .. } => 2,
                                _ => 1,
                            };
                            if matches!(
                                statement,
                                Statement::While { .. }
                                    | Statement::For { .. }
                                    | Statement::ForBorrow { .. }
                                    | Statement::ForOwn { .. }
                            ) && children[child..child + count]
                                .iter()
                                .any(|value| *value != 0)
                            {
                                return Err((
                                    "streaming stdin Open cannot execute in a loop",
                                    expression.span,
                                ));
