                    }
                    _ => children.iter().copied().fold(0, u8::saturating_add),
                };
                if cost > 1 {
                    return Err((
                        "streaming stdin Open may execute at most once per invocation path",
                        expression.span,
                    ));
                }
                values.truncate(offset);
                values.push(cost);
            }
        }
    }
    Ok(values.pop().unwrap_or(0))
}

