        };
        let keys: Vec<_> = (1usize..=4096)
            .map(|n| n * 16)
            .filter(|pointer| ExtendedRegistry::home(*pointer, 63) == 63)
            .take(17)
            .collect();
        assert_eq!(keys.len(), 17);
