            let pointer = owner.as_ptr() as usize;
            let (_, report) = watch_free_order(&[pointer], || {
                drop(owner);
                let mut replacement = vec![0u8; 64];
                replacement.reserve_exact(64);
                std::hint::black_box(&replacement);
                drop(replacement);
            });
            report
        });
        assert!(
            !report.invalid && !metrics.invalid,
