fn return_type(op: VecOp, ty: &Type) -> bool {
    if op.returns_owner() {
        generic_vec(ty)
    } else if matches!(op, VecOp::Len | VecOp::Capacity) {
        *ty == Type::Usize
    } else {
        generic_parameter(ty)
    }
}

