pub(crate) fn with_authenticated_context<T>(
    root: &Path,
    entry_module: &str,
    target: crate::workspace_analysis::WorkspaceAnalysisTarget,
    direction: crate::workspace_analysis::WorkspaceAnalysisDirection,
    depth: usize,
    max_nodes: usize,
    operation: impl FnOnce(
