    let observe = |current, limit| {
        with_limit_usage_refusal(limit, || {
            measure(|| {
                let registry = LayoutRegistry::new(&programs, &authored);
                let mut owner = match Receiver::acquire() {
                    Ok(owner) => owner,
                    Err(_) => return false,
                };
                let ok = if current {
                    match construct_transient(
                        &programs[0],
                        &authored,
                        &programs,
                        &registry,
                        None,
                        &mut owner,
                    ) {
                        Ok(view) => {
                            drop(view);
                            true
                        }
                        Err(failure) => {
                            drop(failure);
                            false
                        }
                    }
                } else {
                    match super::super::before_alias::construct_using(
                        &programs[0],
                        &authored,
                        &programs,
                        &registry,
                        None,
                        &mut owner,
                    ) {
                        Ok(view) => {
                            drop(view);
                            true
                        }
                        Err(failure) => {
                            drop(failure);
                            false
                        }
                    }
                };
                drop(owner);
                drop(registry);
                ok
