                );
            }
            assert_eq!(
                std::fs::read_to_string(root.join("src/schema.spx")).unwrap(),
                canonical(&source)
            );
            Ok((bundle, entries))
        })
        .unwrap();
    let changed = canonical(&source.replace("retry:usize", "retry:i64"));
